template <typename T>
T maxOf(T a, T b)
{
    return a > b ? a : b;
}

unitTests:
TEST("ints") { CHECK_EQ(maxOf(3, 7), 7); CHECK_EQ(maxOf(-1, -9), -1); }
TEST("doubles") { CHECK_NEAR(maxOf(2.5, 1.5), 2.5, 1e-12); }
TEST("strings compare alphabetically") { CHECK_EQ(maxOf(std::string{ "apple" }, std::string{ "banana" }), "banana"); }
TEST("chars") { CHECK_EQ(maxOf('a', 'z'), 'z'); }

